{/* Five people, three faces, and a +2. */}
<Avatar.Group max={3}>
  {members.map((member) => (
    <Avatar key={member.id} source={{ uri: member.avatarUrl }} fallback={member.initials} />
  ))}
</Avatar.Group>

{/* Three faces out of forty — a +37. */}
<Avatar.Group max={3} total={40}>
  {members.slice(0, 3).map((member) => (
    <Avatar key={member.id} source={{ uri: member.avatarUrl }} fallback={member.initials} />
  ))}
</Avatar.Group>
